const requested=new URLSearchParams(location.search).get('species')||'pineapple';
const root=document.querySelector('#speciesContent');
const esc=value=>String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const summaries={pineapple:'Integrated pineapple evidence across fruit development, tissue biology and stress research.',passionfruit:'Integrated passion fruit evidence across development, tissue biology, disease and stress research.',avocado:'Integrated avocado evidence for fruit development, physiology and comparative analysis.',sugarapple:'Integrated sugar apple evidence organized for growth, development and stress discovery.',guava:'Integrated guava evidence for developmental, functional and stress-response research.',rambutan:'Integrated rambutan evidence for species development and comparative discovery.',wampee:'Integrated wampee evidence across fruit development, tissues and long-read transcriptomics.',dragonfruit:'Integrated dragon fruit evidence across development, epigenomics and single-cell research.',litchi:'Integrated litchi evidence across flowering, fruit development, chilling response and single-cell biology.',durian:'Integrated durian evidence supporting fruit, flower and tissue development research.',longan:'Integrated longan evidence across development, chromatin accessibility and expression biology.',mango:'Integrated mango evidence across development, stress response and epigenomic regulation.',cashew:'Integrated cashew evidence organized for growth, development and stress discovery.'};
Promise.all([fetch('data/genomes.json').then(r=>r.json()),fetch('data/advanced-omics.json').then(r=>r.json())]).then(([genomes,omics])=>{
  const species=genomes.species.find(item=>item.key===requested)||genomes.species[0],records=omics.species[species.key]||[];
  document.title=`${species.commonName} | TropicalfruitLLM v1.0`;
  const themeCard=(theme,title,text)=>{const types=[...new Set(records.filter(record=>record.theme===theme).map(record=>record.omicsType))];return `<a class="theme-card ${theme}" href="omics.html?species=${encodeURIComponent(species.key)}&theme=${theme}"><small>${theme==='development'?'BIOLOGICAL DEVELOPMENT':'ENVIRONMENTAL RESPONSE'}</small><h2>${title}</h2><p>${text}</p><div class="tag-list">${types.length?types.map(type=>`<span>${esc(type)}</span>`).join(''):'<span>Curated profile</span>'}</div><b>View omics layers →</b></a>`};
  root.innerHTML=`<section class="species-summary-hero"><figure><img src="assets/species-natural-hd-v5/${encodeURIComponent(species.key)}.jpg?v=29" alt="${esc(species.commonName)} fruit growing naturally on the plant"></figure><div class="species-title"><small>SPECIES EVIDENCE PROFILE</small><h1>${esc(species.commonName)}</h1><em>${esc(species.scientificName)}</em><p>${esc(summaries[species.key]||'Integrated tropical fruit genomic and multi-omics evidence.')}</p></div></section><section class="theme-section"><div class="section-title"><h2>Choose a biological theme</h2><p>Evidence is organized first by biological question. Open a theme to view the available sequencing and omics data types.</p></div><div class="theme-grid">${themeCard('development','Growth & Development','Fruit, flower, seed, tissue, organ and developmental-stage evidence.')} ${themeCard('stress','Stress Response','Abiotic stress, disease, pathogen, temperature and environmental-response evidence.')}</div></section>`;
}).catch(()=>{root.innerHTML='<p class="loading">Species data are temporarily unavailable.</p>'});
